; F1 (RAMEN 0; IDB 10h / 20h; FFFFF; words across DFF / EFF / FFF). Generated by validation/v35s/onchip.py emit: the
; image also preloads the vector stubs and the data in onchip.py.
    BR main
handler:                ; 0103h: AL = the vector (from the stub)
    MOV BL, AL
    XOR AW, AW
    MOV DS0, AW
    MOV [7E00h], BL
    MOV BP, SP
    MOV AW, [BP]
    MOV [7E02h], AW
    MOV AW, [BP+2]
    MOV [7E04h], AW
    MOV AW, [BP+4]
    MOV [7E06h], AW
    MOV [7E08h], SP
    MOV AH, 02h         ; BRKI = 1: the OUT below does not trap
    MOV PSW, AH
    MOV DW, 0FF02h
    OUT DW, AL
    HALT
hspin:
    BR hspin
main:
    XOR AW, AW
    MOV SS, AW
    MOV SP, 7FFEh
    DI

    MOV AW, 0F000h
    MOV DS1, AW
    MOV AW, 0800h
    MOV DS0, AW
    MOV BW, 0FE00h
    MOV AW, 0C0C1h
    MOV CW, 0020h
pre:
    DB 26h
    MOV [BW], AW
    ADD AW, 0202h
    INC BW
    INC BW
    DBNZ pre
    ; internal RAM at E10 / E11 <- 5AA5h; IDB at FFFFF and FFF
    DB 26h
    MOV word [0FE10h], 5AA5h
    DB 26h
    MOV AL, [0FFFFh]
    MOV [0000h], AL
    ; FFFFF as SS:000F with SS = FFFFh (independent of IDB); SS back to 0 at the end
    MOV AW, 0FFFFh
    MOV SS, AW
    DB 36h
    MOV AL, [000Fh]
    MOV [0001h], AL
    ; RAMEN = 0 (PRC 0Eh): E10 read as a word, E10 written, the AW slot read; PRC read
    MOV AW, 1234h
    DB 26h
    MOV byte [0FFEBh], 0Eh
    DB 26h
    MOV CW, [0FE10h]
    MOV [0002h], CW
    DB 26h
    MOV CW, [0FEFEh]
    MOV [0004h], CW
    DB 26h
    MOV word [0FE20h], 0C3C3h
    DB 26h
    MOV CL, [0FFEBh]
    MOV [0006h], CL
    DB 26h
    MOV CW, [0FEEEh]
    MOV [0008h], CW
    DB 26h
    MOV byte [0FFEBh], 4Eh
    DB 26h
    MOV CW, [0FE10h]
    MOV [000Ah], CW
    DB 26h
    MOV CW, [0FE20h]
    MOV [000Ch], CW
    DB 26h
    MOV CW, [0FEFEh]
    MOV [000Eh], CW
    ; IDB <- 10h by a write at FFF of the page
    DB 26h
    MOV byte [0FFFFh], 10h
    DB 36h
    MOV AL, [000Fh]
    MOV [0010h], AL
    DB 26h
    MOV CW, [0FE10h]
    MOV [0012h], CW
    DB 26h
    MOV CL, [0FFEBh]
    MOV [0014h], CL
    DB 26h
    MOV CL, [0FFFFh]
    MOV [0015h], CL
    MOV BW, 1000h
    MOV DS1, BW
    DB 26h
    MOV CW, [0E10h]
    MOV [0016h], CW
    DB 26h
    MOV CW, [0EFEh]
    MOV [0018h], CW
    DB 26h
    MOV CL, [0FEBh]
    MOV [001Ah], CL
    DB 26h
    MOV CL, [0FFFh]
    MOV [001Bh], CL
    DB 26h
    MOV word [0E30h], 6996h
    DB 26h
    MOV word [0F30h], 0000h
    MOV BW, 0F000h
    MOV DS1, BW
    DB 26h
    MOV CW, [0FE30h]
    MOV [001Ch], CW
    ; a write at FFFFF with IDB = 10h: <- 20h
    DB 36h
    MOV byte [000Fh], 20h
    DB 36h
    MOV AL, [000Fh]
    MOV [0020h], AL
    MOV BW, 1000h
    MOV DS1, BW
    DB 26h
    MOV CL, [0FFFh]
    MOV [0021h], CL
    DB 26h
    MOV CW, [0E10h]
    MOV [0022h], CW
    MOV BW, 2000h
    MOV DS1, BW
    DB 26h
    MOV CL, [0FFFh]
    MOV [0024h], CL
    DB 26h
    MOV CW, [0E10h]
    MOV [0026h], CW
    DB 26h
    MOV CW, [0E30h]
    MOV [0028h], CW
    ; back to FFh: a write at FFFFF
    DB 36h
    MOV byte [000Fh], 0FFh
    DB 36h
    MOV AL, [000Fh]
    MOV [002Ah], AL
    ; (whichever page holds IDB now: FF to both relocated FFFs, external if not)
    MOV BW, 1000h
    MOV DS1, BW
    DB 26h
    MOV byte [0FFFh], 0FFh
    MOV BW, 2000h
    MOV DS1, BW
    DB 26h
    MOV byte [0FFFh], 0FFh
    MOV BW, 0F000h
    MOV DS1, BW
    DB 26h
    MOV CW, [0FE10h]
    MOV [002Ch], CW
    DB 26h
    MOV CW, [0FE30h]
    MOV [002Eh], CW
    ; the boundaries: words at DFF (external + internal), EFF (RAM + SFR), and FFF read
    DB 26h
    MOV CW, [0FDFFh]
    MOV [0030h], CW
    DB 26h
    MOV CW, [0FEFFh]
    MOV [0032h], CW
    DB 26h
    MOV word [0FDFFh], 8182h
    DB 26h
    MOV word [0FEFFh], 9394h
    DB 26h
    MOV CW, [0FE00h]
    MOV [0034h], CW
    DB 26h
    MOV CW, [0FEFEh]
    MOV [0036h], CW
    DB 26h
    MOV CW, [0FF00h]
    MOV [0038h], CW
    DB 26h
    MOV CW, [0FDFEh]
    MOV [003Ah], CW
    ; a word at FFFFE (the page's FFE and IDB)
    DB 26h
    MOV CW, [0FFFEh]
    MOV [003Ch], CW
    XOR AW, AW
    MOV SS, AW
    MOV DW, 0FF00h
    OUT DW, AL
    HALT
done:
    BR done

